  function insert(s){const a=input.selectionStart??input.value.length,b=input.selectionEnd??a;const before=input.value.slice(0,a),after=input.value.slice(b);state.expr=before+s+after;input.value=state.expr;input.focus();const pos=before.length+s.length;input.setSelectionRange(pos,pos);save()}
  function deleteAt(){const a=input.selectionStart??input.value.length,b=input.selectionEnd??a;if(a!==b){state.expr=input.value.slice(0,a)+input.value.slice(b);input.setSelectionRange(a,a)}else if(a>0){state.expr=input.value.slice(0,a-1)+input.value.slice(a);input.setSelectionRange(a-1,a-1)}input.value=state.expr;input.focus();save()}
  function handleKey(act,alt,alphaCode){
    if(!state.powered&&act!=='power')return;
    if(act==='shift'){shift=!shift;alpha=false;renderKeys();$('#shiftIndicator').classList.toggle('indicator-off',!shift);$('#alphaIndicator').classList.toggle('indicator-off',!alpha);return}
    if(act==='alpha'){alpha=!alpha;shift=false;renderKeys();$('#shiftIndicator').classList.toggle('indicator-off',!shift);$('#alphaIndicator').classList.toggle('indicator-off',!alpha);return}
    if(shift){
      shift=false;renderKeys();$('#shiftIndicator').classList.toggle('indicator-off',true);
      if(act==='S↔D'){engineeringStep();return}
      if(act==='menu'){openSetup();return}
      if(act==='power'||act==='AC'){state.powered=!state.powered;$('#calculator').classList.toggle('powered-off',!state.powered);toast(state.powered?'Calculator on':'Calculator display off');return}
      if(act==='='){solveNumeric();return}
      if(act==='STO'){recallMemory();return}
      if(act==='*'&&alt==='nPr('){insert('nPr(');return}
      if(act==='/'&&alt==='nCr('){insert('nCr(');return}
      if(act==='+'&&alt==='π'){insert('pi');return}
      if(act==='x2'){insert('^3');return}
      if(act==='inverse'){insert('sqrt(');return}
      if(act==='dms'&&alt==='FACT'){optionAction('prime');return}
      if(act==='memoryPlus'&&alt==='M−'){memoryAdd(-1);return}
      if(act==='engineering'&&alt==='RECALL'){recallMemory();return}
      if(act==='constants'){renderConstants();$('#constantsDialog').showModal();return}
      if(act==='conversion'){populateConvert();$('#convertDialog').showModal();return}
      if(act==='reset'){$('#resetCalc').click();return}
      const shifted={'sin(':'asin(','cos(':'acos(','tan(':'atan(','log(':'10^(','ln(':'exp(','sqrt(':'^3','^':'cbrt(','/':'pi','*':'e','.':'%','!':'abs(','Ans':'F','10^(':'exp('};
      if(shifted[act]){insert(shifted[act]);return}
      if(['left','right','up','down'].includes(act)){handleKey(act);return}
      if(act==='DEL'){deleteAt();return}
    }
    if(alpha){alpha=false;renderKeys();$('#alphaIndicator').classList.toggle('indicator-off',true);const v=(alphaCode||alt||'').toUpperCase();if(['A','B','C','D','E','F','M','X','Y'].includes(v)){insert(v==='X'?'x':v==='Y'?'y':v);return}if(alt&&alt!=='ALPHA'){insert(alt);return}}
    if(act==='menu'){openMenu();return}
    if(act==='options'){openOptions();return}
    if(act==='integral'){integralTool();return}
    if(act==='left'||act==='right'){const p=input.selectionStart??0,n=act==='left'?Math.max(0,p-1):Math.min(input.value.length,p+1);input.focus();input.setSelectionRange(n,n);return}
    if(act==='up'){loadHistory(-1);return}if(act==='down'){loadHistory(1);return}
    if(act==='AC'){state.expr='';input.value='';error.textContent='';result.textContent='0';state.result='0';save();return}
    if(act==='DEL'){deleteAt();return}
    if(act==='='){calculate();return}
    if(act==='S↔D'){toggleSD();return}
    if(act==='STO'){storeAns();return}
    if(act==='power'){state.powered=!state.powered;$('#calculator').classList.toggle('powered-off',!state.powered);toast(state.powered?'Calculator on':'Calculator display off');return}
    if(act==='x2'){insert('^2');return}
    if(act==='inverse'){insert('^(-1)');return}
    if(act==='dms'){dmsStep();return}
    if(act==='engineering'){engineeringStep();return}
    if(act==='memoryPlus'){memoryAdd();return}
    if(act==='constants'){renderConstants();$('#constantsDialog').showModal();return}
    if(act==='conversion'){populateConvert();$('#convertDialog').showModal();return}
    if(act==='reset'){$('#resetCalc').click();return}
    if(act==='neg'){insert('-');return}
    if(act==='Ans'){insert('Ans');return}
    insert(act)
  }
  function memoryAdd(sign=1){const next=(Number(state.variables.M)||0)+sign*(Number(state.ans)||0);state.variables.M=next;state.memory=next;save();render();toast(sign<0?'M− updated':'M+ updated')}
  function dmsStep(){try{const value=evalExpr(input.value||String(state.ans));const sign=value<0?'−':'',absolute=Math.abs(value),degrees=Math.floor(absolute),minutesFloat=(absolute-degrees)*60,minutes=Math.floor(minutesFloat),seconds=(minutesFloat-minutes)*60;setAnswer(`${sign}${degrees}°${minutes}′${fmt(seconds)}″`,value)}catch(e){fail(e)}}
  function toggleSD(){const n=Number(state.ans);if(!Number.isFinite(n)){toast('No numeric answer to convert');return}if(state.result.includes('/'))setAnswer(fmt(n),n);else{const [p,q]=approxFraction(n,1000000);let text;if(q===1)text=String(p);else if(state.fraction==='Mixed'&&Math.abs(p)>=q){const whole=Math.trunc(p/q),rem=Math.abs(p%q);text=rem?`${whole} ${rem}/${q}`:String(whole)}else text=`${p}/${q}`;setAnswer(text,n)}}
  function engineeringStep(){const n=Number(state.ans);if(!Number.isFinite(n)||n===0){setAnswer('0',0);return}const exponent=Math.floor(Math.log10(Math.abs(n))/3)*3,mantissa=n/10**exponent,symbol=({'-12':'p','-9':'n','-6':'μ','-3':'m','0':'','3':'k','6':'M','9':'G','12':'T'})[exponent];setAnswer(state.engineering&&symbol!==undefined?`${fmt(mantissa)} ${symbol}`:`${fmt(mantissa)} × 10^${exponent}`,n)}  function approxFraction(x,maxDen){if(!Number.isFinite(x))return[0,1];const sign=Math.sign(x);x=Math.abs(x);let bestN=Math.round(x),bestD=1,best=Infinity;for(let d=1;d<=Math.min(maxDen,10000);d++){const n=Math.round(x*d),e=Math.abs(x-n/d);if(e<best){best=e;bestN=n;bestD=d;if(e<1e-12)break}}const gcd=(a,b)=>b?gcd(b,a%b):a;const g=gcd(bestN,bestD);return[sign*bestN/g,bestD/g]}
  function storeAns(){const name=prompt('Store the current answer in A–F, M, x, or y');if(!name)return;const k=name.trim().toUpperCase();if(!['A','B','C','D','E','F','M','X','Y'].includes(k)){toast('Choose A–F or M');return}state.variables[k]=state.ans;if(k==='M')state.memory=state.ans;save();render();toast(`Answer stored in ${k}`)}
  function recallMemory(){const name=prompt('Recall variable A–F, M, x, or y');if(!name)return;const k=name.trim().toUpperCase();if(!['A','B','C','D','E','F','M','X','Y'].includes(k)){toast('Choose A–F, M, x, or y');return}if(!(k in state.variables)){toast(`No value stored in ${k}`);return}insert(k==='X'?'x':k==='Y'?'y':k);}  function calculate(){state.expr=input.value;if(state.mode!=='calc'){const action={complex:'complex',base:'base',matrix:'matrix',vector:'vector',stats:'stats',dist:'distribution',sheet:'sheetRecalc',table:'tableRun',equation:'equation',inequality:'inequality',ratio:'ratio'}[state.mode];if(action){runWorkbench(action);return}}try{const value=evalExpr(state.expr);if(typeof value!=='number'||!Number.isFinite(value))throw Error('Result is outside the real number range');setAnswer(fmt(value),value);pushHistory(state.expr,state.result)}catch(e){fail(e)}save()}  function solveNumeric(){if(!state.expr){toast('Enter an equation first');return}try{const expr=state.expr.replace(/=+/g,'-(')+')',f=x=>evalExpr(expr,{x}),seed=Number(state.variables.X??0);let x=seed,root=null;for(let k=0;k<60;k++){const y=f(x);if(Math.abs(y)<1e-10){root=x;break}const h=1e-5*Math.max(1,Math.abs(x)),d=(f(x+h)-f(x-h))/(2*h);if(!Number.isFinite(d)||Math.abs(d)<1e-12)break;const next=x-y/d;if(!Number.isFinite(next)||Math.abs(next)>1e12)break;if(Math.abs(next-x)<1e-10){root=next;break}x=next}if(root===null){const candidates=[];for(const radius of [10,100,1000]){let lastX=-radius,lastY;try{lastY=f(lastX)}catch{}for(let i=1;i<=4000;i++){const curX=-radius+2*radius*i/4000;let curY;try{curY=f(curX)}catch{lastX=curX;lastY=undefined;continue}if(lastY!==undefined&&(lastY===0||curY===0||Math.sign(lastY)!==Math.sign(curY))){let lo=lastX,hi=curX,fl=lastY;for(let j=0;j<70;j++){const mid=(lo+hi)/2,fm=f(mid);if(Math.abs(fm)<1e-12){lo=hi=mid;break}if(Math.sign(fm)===Math.sign(fl)){lo=mid;fl=fm}else hi=mid}candidates.push((lo+hi)/2)}lastX=curX;lastY=curY}if(candidates.length)break}if(candidates.length)root=candidates.sort((a,b)=>Math.abs(a-seed)-Math.abs(b-seed))[0]}if(root===null)throw Error('Could not locate a real root; try a closer starting value');setAnswer(`x ≈ ${fmt(root)}  (numerical)`,root);pushHistory(`SOLVE(${state.expr})`,state.result)}catch(e){fail(e)}}  function pushHistory(expr,res){if(!expr)return;state.history.unshift({expr,result:res,time:Date.now()});state.history=state.history.slice(0,80);activeHistory=-1;save();renderHistory()}
  function renderHistory(){const host=$('#historyList');host.innerHTML='';if(!state.history.length){host.innerHTML='<div class="empty-state">Your calculations will appear here.</div>';return}state.history.slice(0,40).forEach((h,i)=>{const el=document.createElement('button');el.className='history-entry';el.innerHTML=`<span class="hist-expr">${esc(h.expr)}</span><span class="hist-result">${esc(h.result)}</span>`;el.addEventListener('click',()=>{state.expr=h.expr;input.value=h.expr;input.focus();input.setSelectionRange(h.expr.length,h.expr.length);save()});host.append(el)})}
  function tokenize(src){src=String(src).replace(/[×·]/g,'*').replace(/[÷]/g,'/').replace(/[−–]/g,'-').replace(/π/g,'pi').replace(/√/g,'sqrt').replace(/∠/g,'angle');const raw=[];let i=0;while(i<src.length){if(/\s/.test(src[i])){i++;continue}const sub=src.slice(i);const nm=sub.match(/^(?:\d+\.?\d*|\.\d+)(?:[eE][+-]?\d+)?/);if(nm){raw.push({t:'num',v:Number(nm[0])});i+=nm[0].length;continue}const id=sub.match(/^[A-Za-z_][A-Za-z_0-9]*/);if(id){raw.push({t:'id',v:id[0]});i+=id[0].length;continue}if('+-*/^%!(),'.includes(src[i])){raw.push({t:src[i],v:src[i]});i++;continue}throw Error(`Unexpected character “${src[i]}”`)}const funcs=new Set(['sin','cos','tan','asin','acos','atan','sinh','cosh','tanh','asinh','acosh','atanh','sqrt','cbrt','abs','ln','log','log10','exp','floor','ceil','round','trunc','fact','ncr','npr','min','max','random','randint','dms','toRad','toDeg']);const out=[];for(let j=0;j<raw.length;j++){const cur=raw[j],prev=out[out.length-1];if(prev){const left=prev.t==='num'||prev.t===')'||prev.t==='!'||prev.t==='%'||(prev.t==='id'&&!funcs.has(prev.v.toLowerCase()));const right=cur.t==='num'||cur.t==='('||cur.t==='id';const isFnOpen=prev.t==='id'&&funcs.has(prev.v.toLowerCase())&&cur.t==='(';if(left&&right&&!isFnOpen)out.push({t:'*',v:'*'})}out.push(cur)}return out}
  function evalExpr(src,vars={}){const t=tokenize(src);let p=0;const angleFactor=state.angle==='Rad'?1:state.angle==='Gra'?Math.PI/200:Math.PI/180;const fromRad=x=>state.angle==='Rad'?x:state.angle==='Gra'?x*200/Math.PI:x*180/Math.PI;const prec={'+':1,'-':1,'*':2,'/':2,'%':2,'^':4};function primary(){const q=t[p++];if(!q)throw Error('Expression is incomplete');if(q.t==='num')return q.v;if(q.t==='+'||q.t==='-'){const n=expr(3);return q.t==='-'?-n:n}if(q.t==='('){const n=expr(0);if(t[p++]?.t!==')')throw Error('Missing closing parenthesis');return n}if(q.t==='id'){const id=q.v.toLowerCase();if(t[p]?.t==='('){p++;const args=[];if(t[p]?.t!==')'){do{args.push(expr(0));if(t[p]?.t!==',')break;p++}while(true)}if(t[p++]?.t!==')')throw Error(`Missing ) after ${q.v}`);return fn(id,args)}if(id==='pi')return Math.PI;if(id==='e')return Math.E;if(id==='ans')return Number(vars.Ans??state.ans);if(id==='x'&&'x'in vars)return vars.x;if(id==='a'&&'a'in vars)return vars.a;const k=q.v.toUpperCase();if(k in state.variables)return Number(state.variables[k]);if(k==='I')throw Error('Complex values are handled in Complex mode');throw Error(`Unknown variable “${q.v}”`)}throw Error('Expected a number or opening parenthesis')}
    function fn(id,a){const one=()=>{if(a.length!==1)throw Error(`${id} needs one argument`);return a[0]},two=()=>{if(a.length!==2)throw Error(`${id} needs two arguments`);return a};switch(id){case'sin':return Math.sin(one()*angleFactor);case'cos':return Math.cos(one()*angleFactor);case'tan':return Math.tan(one()*angleFactor);case'asin':return fromRad(Math.asin(one()));case'acos':return fromRad(Math.acos(one()));case'atan':return fromRad(Math.atan(one()));case'sinh':return Math.sinh(one());case'cosh':return Math.cosh(one());case'tanh':return Math.tanh(one());case'asinh':return Math.asinh(one());case'acosh':return Math.acosh(one());case'atanh':return Math.atanh(one());case'sqrt':return Math.sqrt(one());case'cbrt':return Math.cbrt(one());case'abs':return Math.abs(one());case'ln':return Math.log(one());case'log10':return Math.log10(one());case'log':return a.length===1?Math.log10(a[0]):Math.log(a[1])/Math.log(a[0]);case'exp':return Math.exp(one());case'floor':return Math.floor(one());case'ceil':return Math.ceil(one());case'round':return Math.round(one());case'trunc':return Math.trunc(one());case'fact':return factorial(one());case'ncr':{const [n,r]=two();return factorial(n)/(factorial(r)*factorial(n-r))}case'npr':{const [n,r]=two();return factorial(n)/factorial(n-r)}case'min':return Math.min(...a);case'max':return Math.max(...a);case'random':return Math.random();case'randint':{const [lo,hi]=two();return Math.floor(Math.random()*(hi-lo+1))+lo}case'dms':{const [d,m=0,s=0]=a;return Math.sign(d)*(Math.abs(d)+m/60+s/3600)}case'torad':return one()*angleFactor;case'todeg':return fromRad(one());default:throw Error(`Unknown function “${id}”`)}}
    function expr(min){let left=primary();for(;;){const q=t[p];if(q?.t==='!'||q?.t==='%'){if(5<min)break;p++;left=q.t==='!'?factorial(left):left/100;continue}const pr=prec[q?.t];if(pr===undefined||pr<min)break;p++;const right=expr(pr+(q.t==='^'?0:1));switch(q.t){case'+':left+=right;break;case'-':left-=right;break;case'*':left*=right;break;case'/':left/=right;break;case'%':left%=right;break;case'^':left=Math.pow(left,right);break}}return left}const v=expr(0);if(p<t.length)throw Error(`Unexpected “${t[p].v}”`);if(Number.isNaN(v))throw Error('Invalid calculation; check the function domain');if(!Number.isFinite(v))throw Error('Math error: division by zero or overflow');return v}
  function factorial(n){if(!Number.isInteger(n)||n<0||n>69)throw Error('Factorial needs an integer from 0 to 69');let x=1;for(let i=2;i<=n;i++)x*=i;return x}
  function addHistory(expr,res){pushHistory(expr,res)}
  function openMenu(){const g=$('#modeGrid');g.innerHTML='';for(const [name,desc,id]of modes){const b=document.createElement('button');b.className='mode-card '+(state.mode===id?'active':'');b.innerHTML=`<b>${esc(name)}</b><small>${esc(desc)}</small>`;b.onclick=()=>setMode(id);g.append(b)}$('#menuDialog').showModal()}
  function openSetup(){$('#setupDialog').showModal()}
  function openOptions(){const opts={calc:[['Stored formula · CALC','calcStored'],['Numerical derivative','derivative'],['Numerical integral','integral'],['Summation','summation'],['Scientific constants','constants'],['Unit conversion','conversion'],['Random integer','random'],['Prime factorization','prime'],['Coordinate conversion','coordinates']],complex:[['Rectangular ↔ polar','polar'],['Conjugate','conjugate'],['Magnitude and argument','magnitude'],['Real / imaginary parts','parts']],base:[['AND / OR / XOR','bitwise'],['NOT / two’s complement','bitnot']],matrix:[['Set matrix dimensions','matrixSize'],['Identity matrix','identity']],vector:[['Unit vector','unitvec']],stats:[['Descriptive statistics','stats'],['Regression','regression']],dist:[['Distribution calculator','distribution']],sheet:[['Fill selected range','fill'],['Min / Max / Mean / Sum','sheetStats']],table:[['Table settings','table']],equation:[['Solve system / polynomial','equation']],inequality:[['Solve polynomial inequality','inequality']],ratio:[['Ratio solver','ratio']]}[state.mode]||[];const host=$('#optionList');host.innerHTML='';for(const [label,act]of opts){const b=document.createElement('button');b.className='option-button';b.textContent=label;b.onclick=()=>{ $('#optionsDialog').close();optionAction(act)};host.append(b)}$('#optionsDialog').showModal()}
  function optionAction(a){if(a==='constants'){renderConstants();$('#constantsDialog').showModal()}else if(a==='conversion'){populateConvert();$('#convertDialog').showModal()}else if(a==='random'){const v=Math.floor(Math.random()*1000000);state.expr=`randInt(0,999999)`;input.value=state.expr;setAnswer(String(v),v);pushHistory(state.expr,state.result)}else if(a==='prime'){try{const n=Math.abs(Math.trunc(state.ans));if(!n)throw Error('Enter a non-zero integer');let x=n,f=[];for(let d=2;d*d<=x;d++)while(x%d===0){f.push(d);x/=d}if(x>1)f.push(x);setAnswer(`${n} = ${f.join(' × ')}`,n)}catch(e){fail(e)}}else if(a==='coordinates'){coordinateTool()}else if(a==='calcStored'){renderWorkbench('calcStored')}else if(a==='derivative'){derivativeTool()}else if(a==='integral'){integralTool()}else if(a==='summation'){sumTool()}else if(a==='polar'){complexPolarTool()}else if(a==='conjugate'||a==='magnitude'){complexTool(a)}else if(a==='parts'){complexTool('real')}else if(a==='bitwise'||a==='bitnot'){bitTool(a)}else if(a==='matrixSize'){matrixTool()}else if(a==='identity'){matrixIdentity()}else if(a==='unitvec'){vectorTool('unit')}else if(a==='stats'){statsTool()}else if(a==='regression'){statsTool(true)}else if(a==='distribution'){distTool()}else if(a==='fill'){fillSheet()}else if(a==='sheetStats'){sheetStats()}else if(a==='table'){renderWorkbench('table')}else if(a==='equation'){renderWorkbench('equation')}else if(a==='inequality'){renderWorkbench('inequality')}else if(a==='ratio'){renderWorkbench('ratio')}}
  function renderConstants(filter=''){const host=$('#constantList');host.innerHTML='';for(const [name,sym,val,unit]of CONSTANTS.filter(c=>`${c[0]} ${c[1]}`.toLowerCase().includes(filter.toLowerCase()))){const row=document.createElement('button');row.className='constant-row';row.innerHTML=`<span>${esc(name)} <small>${esc(unit)}</small></span><b>${esc(sym)}</b>`;row.onclick=()=>{insert(String(val));$('#constantsDialog').close()};host.append(row)}}
  function populateConvert(){const f=$('#convertFrom'),t=$('#convertTo');f.innerHTML='';t.innerHTML='';for(const cat of [...new Set(UNITS.map(u=>u.cat))]){const a=document.createElement('optgroup'),b=document.createElement('optgroup');a.label=b.label=cat;UNITS.forEach((u,i)=>{if(u.cat===cat){a.append(new Option(u.name,String(i)));b.append(new Option(u.name,String(i)))}});f.append(a);t.append(b)}f.value=String(UNITS.findIndex(u=>u.name==='cm'));t.value=String(UNITS.findIndex(u=>u.name==='in'));$('#convertResult').textContent=''}  function convert(value,from,to){const a=UNITS[from],b=UNITS[to];if(!a||!b||a.cat!==b.cat)return NaN;if(a.kind==='temp'){let c=a.name==='°F'?(value-32)*5/9:a.name==='K'?value-273.15:value;return b.name==='°F'?c*9/5+32:b.name==='K'?c+273.15:c}return value*a.factor/b.factor}
  function coordinateTool(){renderWorkbench('coordinate')}
