  function complexTool(which){renderWorkbench(`complex-${which}`);const op=$('#complexOp',wb);if(op)op.value=which==='conjugate'?'conj':which==='magnitude'?'abs':which}  function bitTool(which){renderWorkbench(which)}
  function matrixTool(){renderWorkbench('matrix')}
