  function polyRoots(c){c=c.slice();while(c.length>1&&Math.abs(c[0])<1e-14)c.shift();const n=c.length-1;if(n<1)return[];if(n===1)return[-c[1]/c[0]];if(n===2){const d=c[1]**2-4*c[0]*c[2];if(d<0)return state.complexRoots?[`(${fmt(-c[1]/(2*c[0]))} + ${fmt(Math.sqrt(-d)/(2*c[0]))}i)`,`(${fmt(-c[1]/(2*c[0]))} − ${fmt(Math.sqrt(-d)/(2*c[0]))}i)`]:[];return[(-c[1]+Math.sqrt(d))/(2*c[0]),(-c[1]-Math.sqrt(d))/(2*c[0])].sort((a,b)=>a-b)}let roots=Array.from({length:n},(_,i)=>({re:Math.cos(2*Math.PI*i/n)*1.2,im:Math.sin(2*Math.PI*i/n)*1.2}));const cmul=(a,b)=>({re:a.re*b.re-a.im*b.im,im:a.re*b.im+a.im*b.re}),cdiv=(a,b)=>{let d=b.re*b.re+b.im*b.im;return{re:(a.re*b.re+a.im*b.im)/d,im:(a.im*b.re-a.re*b.im)/d}},csub=(a,b)=>({re:a.re-b.re,im:a.im-b.im});for(let k=0;k<300;k++)for(let i=0;i<n;i++){let z=roots[i],v={re:c[0],im:0};for(let j=1;j<c.length;j++)v={re:cmul(v,z).re+c[j],im:cmul(v,z).im};let den={re:1,im:0};for(let j=0;j<n;j++)if(j!==i)den=cmul(den,csub(z,roots[j]));roots[i]=csub(z,cdiv(v,den))}return roots.map(z=>Math.abs(z.im)<1e-7?z.re:`(${fmt(z.re)} ${z.im<0?'−':'+'} ${fmt(Math.abs(z.im))}i)`).sort((a,b)=>typeof a==='number'&&typeof b==='number'?a-b:String(a).localeCompare(String(b)))}
